changeSet.sql:
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT CK_MemberPtAssignments_PaymentStatus;
ALTER TABLE app.MemberPtAssignments ADD AmountPaid DECIMAL(19, 4) NOT NULL CONSTRAINT DF_MemberPtAssignments_AmountPaid DEFAULT (0);
ALTER TABLE app.MemberPtAssignments ADD PaymentMethod NVARCHAR(32) NULL;
ALTER TABLE app.MemberPtAssignments ADD PaymentDate DATE NULL;
ALTER TABLE app.MemberPtAssignments ADD PaymentReferenceNumber NVARCHAR(100) NULL;
ALTER TABLE app.MemberPtAssignments ADD PaymentNotes NVARCHAR(2000) NULL;
EXEC(N'ALTER TABLE app.MemberPtAssignments ADD CONSTRAINT CK_MemberPtAssignments_AmountPaid CHECK (AmountPaid >= 0 AND AmountPaid <= Price);');
EXEC(N'ALTER TABLE app.MemberPtAssignments ADD CONSTRAINT CK_MemberPtAssignments_PaymentStatus CHECK (PaymentStatus IN (N''Unpaid'', N''PartiallyPaid'', N''Paid''));');
EXEC(N'ALTER TABLE app.MemberPtAssignments ADD CONSTRAINT CK_MemberPtAssignments_PaymentMethod CHECK (PaymentMethod IS NULL OR PaymentMethod IN (N''Cash'', N''Upi'', N''DebitCard'', N''CreditCard'', N''BankTransfer'', N''OnlinePayment'', N''Cheque'', N''Other''));');
EXEC(N'ALTER TABLE app.MemberPtAssignments ADD CONSTRAINT CK_MemberPtAssignments_PaymentShape CHECK ((AmountPaid = 0 AND PaymentStatus = N''Unpaid'' AND PaymentMethod IS NULL AND PaymentDate IS NULL) OR (AmountPaid > 0 AND PaymentMethod IS NOT NULL AND PaymentDate IS NOT NULL AND ((AmountPaid < Price AND PaymentStatus = N''PartiallyPaid'') OR (AmountPaid = Price AND PaymentStatus = N''Paid''))));');

rollback.sql:
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT CK_MemberPtAssignments_PaymentShape;
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT CK_MemberPtAssignments_PaymentMethod;
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT CK_MemberPtAssignments_PaymentStatus;
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT CK_MemberPtAssignments_AmountPaid;
ALTER TABLE app.MemberPtAssignments DROP CONSTRAINT DF_MemberPtAssignments_AmountPaid;
ALTER TABLE app.MemberPtAssignments DROP COLUMN PaymentNotes, PaymentReferenceNumber, PaymentDate, PaymentMethod, AmountPaid;
ALTER TABLE app.MemberPtAssignments ADD CONSTRAINT CK_MemberPtAssignments_PaymentStatus CHECK (PaymentStatus = N'Unpaid');
